import random, itertools
# exact sampler simulation on scaled integer weights
def draw(weights, k, seed):
    rng = random.Random(seed)
    pool=list(range(len(weights))); w=list(weights); out=[]
    for _ in range(k):
        total=sum(w); bits=(total-1).bit_length(); mod=1<<bits
        if total==mod:
            needle=rng.getrandbits(bits)
        else:
            limit=mod-(mod%total)
            while True:
                x=rng.getrandbits(bits)
                if x<limit:
                    needle=x%total; break
        acc=0
        for i,ww in enumerate(w):
            acc+=ww
            if needle<acc:
                out.append(pool.pop(i)); w.pop(i); break
    return out

# Case A moderate: [9, Fraction(1,100)] -> scaled [900,1], p=1/901
hitsA=[]
for s in range(6000):
    if draw([900,1],1,s)==[1]:
        hitsA.append(s)
print("A (900,1):", hitsA[:5])

